package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// Resources is a workload request or a node capacity. CPU is in millicores and
// memory in MiB; both are non-negative 64-bit integers on the wire.
type Resources struct {
	CPU    int64 `json:"cpu"`
	Memory int64 `json:"memory"`
}

// Node is one candidate node offered by a placement request.
type Node struct {
	Name   string            `json:"name"`
	CPU    int64             `json:"cpu"`
	Memory int64             `json:"memory"`
	Labels map[string]string `json:"labels"`
}

// Placement is one stored scheduling decision: the request payload plus its
// status. Node and Reason are pointers so a rejected record renders them as
// JSON null.
type Placement struct {
	Namespace string            `json:"namespace"`
	Name      string            `json:"name"`
	Queue     string            `json:"queue"`
	Priority  int32             `json:"priority"`
	Resources Resources         `json:"resources"`
	Selector  map[string]string `json:"selector"`
	Nodes     []Node            `json:"nodes"`
	Status    string            `json:"status"`
	Node      *string           `json:"node"`
	Reason    *string           `json:"reason"`
}

// ErrNotFound is returned by Get when no placement matches the identity.
var ErrNotFound = errors.New("placement not found")

// Submit stores p the first time its (namespace, name) identity is seen. On a
// repeated submission it returns the previously stored record. created reports
// whether the row was inserted by this call.
func (s *Store) Submit(ctx context.Context, p *Placement) (stored *Placement, created bool, err error) {
	payload, err := canonicalInput(p)
	if err != nil {
		return nil, false, fmt.Errorf("encode placement: %w", err)
	}

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, false, fmt.Errorf("begin submit: %w", err)
	}
	defer tx.Rollback()

	_, execErr := tx.ExecContext(ctx,
		"INSERT INTO placements (namespace, name, input_json, status, node, reason) VALUES (?, ?, ?, ?, ?, ?)",
		p.Namespace, p.Name, string(payload), p.Status, p.Node, p.Reason,
	)
	if execErr == nil {
		if err := tx.Commit(); err != nil {
			return nil, false, fmt.Errorf("commit submit: %w", err)
		}
		out := *p
		return &out, true, nil
	}
	if !isUniqueViolation(execErr) {
		return nil, false, fmt.Errorf("insert placement: %w", execErr)
	}

	row := tx.QueryRowContext(ctx,
		"SELECT input_json, status, node, reason FROM placements WHERE namespace = ? AND name = ?",
		p.Namespace, p.Name,
	)
	var inputJSON, status string
	var node, reason sql.NullString
	if err := row.Scan(&inputJSON, &status, &node, &reason); err != nil {
		return nil, false, fmt.Errorf("load existing placement: %w", err)
	}
	existing, err := decodeRecord(inputJSON, status, node, reason)
	if err != nil {
		return nil, false, err
	}
	return existing, false, nil
}

// Get fetches a single placement by its identity. It returns ErrNotFound when
// the identity is unknown.
func (s *Store) Get(ctx context.Context, namespace, name string) (*Placement, error) {
	row := s.db.QueryRowContext(ctx,
		"SELECT input_json, status, node, reason FROM placements WHERE namespace = ? AND name = ?",
		namespace, name,
	)
	var inputJSON, status string
	var node, reason sql.NullString
	if err := row.Scan(&inputJSON, &status, &node, &reason); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("get placement: %w", err)
	}
	return decodeRecord(inputJSON, status, node, reason)
}

// ListFilter narrows List; empty fields are ignored. Node never matches a
// rejected record.
type ListFilter struct {
	Namespace string
	Queue     string
	Node      string
}

// List returns committed placements matching f, sorted by namespace then name
// in UTF-8 byte order (SQLite BINARY text ordering).
func (s *Store) List(ctx context.Context, f ListFilter) ([]*Placement, error) {
	var clauses []string
	var args []any
	if f.Namespace != "" {
		clauses = append(clauses, "namespace = ?")
		args = append(args, f.Namespace)
	}
	if f.Queue != "" {
		clauses = append(clauses, "queue = ?")
		args = append(args, f.Queue)
	}
	if f.Node != "" {
		clauses = append(clauses, "node = ?")
		args = append(args, f.Node)
	}
	query := "SELECT input_json, status, node, reason FROM placements"
	if len(clauses) > 0 {
		query += " WHERE " + strings.Join(clauses, " AND ")
	}
	query += " ORDER BY namespace, name"

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("list placements: %w", err)
	}
	defer rows.Close()

	var out []*Placement
	for rows.Next() {
		var inputJSON, status string
		var node, reason sql.NullString
		if err := rows.Scan(&inputJSON, &status, &node, &reason); err != nil {
			return nil, fmt.Errorf("scan placement: %w", err)
		}
		rec, err := decodeRecord(inputJSON, status, node, reason)
		if err != nil {
			return nil, err
		}
		out = append(out, rec)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate placements: %w", err)
	}
	return out, nil
}

func decodeRecord(inputJSON, status string, node, reason sql.NullString) (*Placement, error) {
	var in inputPayload
	if err := json.Unmarshal([]byte(inputJSON), &in); err != nil {
		return nil, fmt.Errorf("decode stored placement: %w", err)
	}
	p := &Placement{
		Namespace: in.Namespace,
		Name:      in.Name,
		Queue:     in.Queue,
		Priority:  in.Priority,
		Resources: in.Resources,
		Selector:  in.Selector,
		Nodes:     in.Nodes,
		Status:    status,
	}
	if node.Valid {
		v := node.String
		p.Node = &v
	}
	if reason.Valid {
		v := reason.String
		p.Reason = &v
	}
	return p, nil
}

func isUniqueViolation(err error) bool {
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "unique constraint failed")
}

package store

import (
	"bytes"
	"encoding/json"
)

// This file is the single definition of what counts as the request content
// of a placement and how omitted fields are defaulted. Three entry points
// rely on it and must not re-implement any part of it:
//   - placement.ParsePlacementInput fills defaults through NormalizeInput,
//   - service.Accept normalizes through NormalizeInput before scheduling,
//   - Submit/SameInput compare and store content through canonicalInput.
//
// The rules:
//   - an omitted (nil) selector, node labels map, or nodes array is
//     equivalent to its explicit empty form ({}, {}, []),
//   - JSON object member order and escape spellings never matter: comparison
//     happens on the re-encoded canonical form, whose object keys are sorted
//     by encoding/json,
//   - the nodes array order is significant: reordering it is different
//     content even when the scheduling result would be identical,
//   - status, node and reason are scheduling results, not request content,
//     and never participate in the comparison.

// inputPayload is the canonical JSON representation of the request half of a
// record. It omits Status/Node/Reason so two submissions can be compared for
// content equality byte-for-byte; encoding/json sorts object keys, while
// array order is preserved. Its field set and JSON names are part of the
// stored format: existing database files hold exactly this encoding.
type inputPayload struct {
	Namespace string            `json:"namespace"`
	Name      string            `json:"name"`
	Queue     string            `json:"queue"`
	Priority  int32             `json:"priority"`
	Resources Resources         `json:"resources"`
	Selector  map[string]string `json:"selector"`
	Nodes     []Node            `json:"nodes"`
}

// NormalizeInput fills the documented defaults in place so every entry point
// behaves the same regardless of how the request was assembled: an omitted
// selector or node labels map becomes an empty object, and an omitted nodes
// array becomes an empty array. It only touches nil fields — explicit values,
// including explicit empty objects, are kept as submitted — and it never
// reorders the candidate array, whose order is significant for content
// comparison.
func NormalizeInput(p *Placement) {
	if p.Selector == nil {
		p.Selector = map[string]string{}
	}
	if p.Nodes == nil {
		p.Nodes = []Node{}
	}
	for i := range p.Nodes {
		if p.Nodes[i].Labels == nil {
			p.Nodes[i].Labels = map[string]string{}
		}
	}
}

// SameInput reports whether the request halves of two placements are equal
// under the documented comparison: omitted selector/labels are treated as
// empty objects, object member order is ignored and array order is kept.
// Scheduling results on either record do not affect the outcome.
func SameInput(a, b *Placement) (bool, error) {
	ab, err := canonicalInput(a)
	if err != nil {
		return false, err
	}
	bb, err := canonicalInput(b)
	if err != nil {
		return false, err
	}
	return bytes.Equal(ab, bb), nil
}

// canonicalInput encodes the request half of p in its canonical form. It
// works on a copy so callers can compare records they still own without
// having defaults filled into their structs.
func canonicalInput(p *Placement) ([]byte, error) {
	cp := *p
	if p.Nodes != nil {
		cp.Nodes = make([]Node, len(p.Nodes))
		copy(cp.Nodes, p.Nodes)
	}
	NormalizeInput(&cp)
	in := inputPayload{
		Namespace: cp.Namespace,
		Name:      cp.Name,
		Queue:     cp.Queue,
		Priority:  cp.Priority,
		Resources: cp.Resources,
		Selector:  cp.Selector,
		Nodes:     cp.Nodes,
	}
	data, err := json.Marshal(in)
	if err != nil {
		return nil, err
	}
	return data, nil
}

// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"fmt"

	_ "modernc.org/sqlite"
)

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	// Serialize access through one connection: combined with WAL this keeps
	// concurrent submissions free of busy errors while the UNIQUE constraint
	// remains the guarantee that one identity is stored exactly once.
	db.SetMaxOpenConns(1)
	if _, err := db.Exec("PRAGMA busy_timeout=5000"); err != nil {
		db.Close()
		return nil, fmt.Errorf("set busy timeout: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS placements (
	namespace  TEXT NOT NULL,
	name       TEXT NOT NULL,
	input_json TEXT NOT NULL,
	status     TEXT NOT NULL,
	node       TEXT,
	reason     TEXT,
	queue      TEXT NOT NULL GENERATED ALWAYS AS (json_extract(input_json, '$.queue')) VIRTUAL,
	PRIMARY KEY (namespace, name)
);

CREATE INDEX IF NOT EXISTS idx_placements_ns   ON placements (namespace);
CREATE INDEX IF NOT EXISTS idx_placements_queue ON placements (queue);
CREATE INDEX IF NOT EXISTS idx_placements_node  ON placements (node);
`

