229	func TestAcceptConcurrentIdenticalSubmissionsStoreOneRecord(t *testing.T) {
230		st, svc := newService(t)
231		const n = 24
232		var wg sync.WaitGroup
233		outcomes := make([]Outcome, n)
234		errs := make([]error, n)
235		wg.Add(n)
236		for i := 0; i < n; i++ {
237			go func(i int) {
238				defer wg.Done()
239				_, outcomes[i], errs[i] = svc.Accept(context.Background(), samplePlacement())
240			}(i)
241		}
242		wg.Wait()
243	
244		var created, identical int
245		for i := range outcomes {
246			if errs[i] != nil {
247				t.Fatalf("goroutine %d: %v", i, errs[i])
248			}
249			switch outcomes[i] {
250			case Created:
251				created++
252			case Identical:
253				identical++
254			default:
255				t.Fatalf("unexpected outcome %d", outcomes[i])
256			}
257		}
258		if created != 1 || identical != n-1 {
259			t.Fatalf("outcome counts: created=%d identical=%d, want 1 and %d", created, identical, n-1)
260		}
261		recs, err := st.List(context.Background(), store.ListFilter{})
262		if err != nil {
263			t.Fatalf("list: %v", err)
264		}
265		if len(recs) != 1 {
266			t.Fatalf("stored records = %d, want 1", len(recs))
267		}
