1	package api
2	
3	import (
4		"fmt"
5		"net/http"
6		"testing"
7	)
8	
9	// Regression tests for the unified defaulting/content-comparison rules: every
10	// acceptance verdict (201/200/409/400) is checked together with what the
11	// query endpoints actually hold afterwards, never by the scheduling result
12	// alone.
13	
14	func listBodies(t *testing.T, h http.Handler, target string) []any {
15		t.Helper()
16		rec := doRequest(t, h, http.MethodGet, target, "")
17		if rec.Code != http.StatusOK {
18			t.Fatalf("GET %s = %d: %s", target, rec.Code, rec.Body.String())
19		}
20		return decodeBody(t, rec)["items"].([]any)
21	}
22	
23	// Equivalent submissions — omitted vs explicit defaults, reordered members,
24	// escaped member names — produce one record; the query view agrees.
25	func TestRegressionEquivalentContentRegistersOnce(t *testing.T) {
26		_, h := newTestRouter(t)
27	
28		first := postPlacement(t, h, `{
29		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
30		  "resources": {"memory": 64, "cpu": 100},
31		  "nodes": [{"name": "n", "cpu": 200, "memory": 128}]
32		}`)
33		if first.Code != http.StatusCreated {
34			t.Fatalf("first = %d: %s", first.Code, first.Body.String())
35		}
36		// The returned record keeps the full input with defaults rendered.
37		if got := decodeBody(t, first); got["selector"] == nil || got["status"] != "placed" {
38			t.Fatalf("first record incomplete: %s", first.Body.String())
39		}
40	
41		variant := postPlacement(t, h, `{
42		  "nodes": [{"labels": {}, "memory": 128, "cpu": 200, "name": "n"}],
43		  "resources": {"cpu": 100, "memory": 64},
44		  "selector": {},
45		  "priority": 1, "queue": "q", "name": "job", "namespace": "ns"
46		}`)
47		if variant.Code != http.StatusOK {
48			t.Fatalf("variant = %d, want 200: %s", variant.Code, variant.Body.String())
49		}
50		if variant.Body.String() != first.Body.String() {
51			t.Fatalf("equivalent retry returned a different record:\n%s\n%s", first.Body.String(), variant.Body.String())
52		}
53	
54		// The query view holds exactly that one record.
55		single := doRequest(t, h, http.MethodGet, "/v1/placements?namespace=ns&name=job", "")
56		if single.Code != http.StatusOK || single.Body.String() != first.Body.String() {
57			t.Fatalf("single query = %d: %s", single.Code, single.Body.String())
58		}
59		if items := listBodies(t, h, "/v1/placements?namespace=ns"); len(items) != 1 {
60			t.Fatalf("list holds %d records, want 1", len(items))
61		}
62	}
63	
64	// Node reorder and priority change are content conflicts even when the
65	// scheduling result would be identical; the stored record and list survive.
66	func TestRegressionContentConflictsLeaveStoreUntouched(t *testing.T) {
67		_, h := newTestRouter(t)
68	
69		body := `{
70		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
71		  "resources": {"cpu": 1, "memory": 1},
72		  "nodes": [
73		    {"name": "n1", "cpu": 10, "memory": 10, "labels": {}},
74		    {"name": "n2", "cpu": 10, "memory": 10, "labels": {}}
75		  ]
76		}`
77		first := postPlacement(t, h, body)
78		if first.Code != http.StatusCreated {
79			t.Fatalf("first = %d: %s", first.Code, first.Body.String())
80		}
81	
82		reordered := `{
83		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
84		  "resources": {"cpu": 1, "memory": 1},
85		  "nodes": [
86		    {"name": "n2", "cpu": 10, "memory": 10, "labels": {}},
87		    {"name": "n1", "cpu": 10, "memory": 10, "labels": {}}
88		  ]
89		}`
90		expectErrorCode(t, postPlacement(t, h, reordered), http.StatusConflict, "PlacementConflictError")
91	
92		reprioritized := `{
93		  "namespace": "ns", "name": "job", "queue": "q", "priority": 2,
94		  "resources": {"cpu": 1, "memory": 1},
95		  "nodes": [
96		    {"name": "n1", "cpu": 10, "memory": 10, "labels": {}},
97		    {"name": "n2", "cpu": 10, "memory": 10, "labels": {}}
98		  ]
99		}`
100		expectErrorCode(t, postPlacement(t, h, reprioritized), http.StatusConflict, "PlacementConflictError")
101	
102		// Neither conflict added or rewrote anything.
103		single := doRequest(t, h, http.MethodGet, "/v1/placements?namespace=ns&name=job", "")
104		if single.Code != http.StatusOK || single.Body.String() != first.Body.String() {
105			t.Fatalf("record changed after conflicts: %d %s", single.Code, single.Body.String())
106		}
107		if items := listBodies(t, h, "/v1/placements"); len(items) != 1 {
108			t.Fatalf("list holds %d records, want 1", len(items))
109		}
110	}
111	
112	// A rejected record obeys the same retry/conflict rules; a retry that would
113	// now schedule differently is still a content conflict, not a new decision.
114	func TestRegressionRejectedRecordRetryAndConflict(t *testing.T) {
115		_, h := newTestRouter(t)
116	
117		rejected := `{
118		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
119		  "resources": {"cpu": 2000, "memory": 256},
120		  "nodes": [{"name": "n", "cpu": 1000, "memory": 512}]
121		}`
122		first := postPlacement(t, h, rejected)
123		if first.Code != http.StatusCreated {
124			t.Fatalf("first = %d: %s", first.Code, first.Body.String())
125		}
126		if got := decodeBody(t, first); got["status"] != "rejected" || got["node"] != nil || got["reason"] != "no_eligible_node" {
127			t.Fatalf("setup: want rejected record, got %s", first.Body.String())
128		}
129	
130		// Same content, spelled with explicit defaults and reordered members.
131		retry := postPlacement(t, h, `{
132		  "selector": {}, "priority": 1, "queue": "q", "name": "job", "namespace": "ns",
133		  "resources": {"memory": 256, "cpu": 2000},
134		  "nodes": [{"labels": {}, "memory": 512, "cpu": 1000, "name": "n"}]
135		}`)
136		if retry.Code != http.StatusOK {
137			t.Fatalf("retry = %d, want 200: %s", retry.Code, retry.Body.String())
138		}
139		if retry.Body.String() != first.Body.String() {
140			t.Fatalf("retry returned a different record:\n%s\n%s", retry.Body.String(), first.Body.String())
141		}
142	
143		// A smaller request on the same identity would be placeable — the
144		// scheduling outcome must not replace the content comparison.
145		placeable := `{
146		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
147		  "resources": {"cpu": 100, "memory": 64},
148		  "nodes": [{"name": "n", "cpu": 1000, "memory": 512}]
149		}`
150		expectErrorCode(t, postPlacement(t, h, placeable), http.StatusConflict, "PlacementConflictError")
151	
152		single := doRequest(t, h, http.MethodGet, "/v1/placements?namespace=ns&name=job", "")
153		if single.Code != http.StatusOK || single.Body.String() != first.Body.String() {
154			t.Fatalf("rejected record changed: %d %s", single.Code, single.Body.String())
155		}
156		if items := listBodies(t, h, "/v1/placements"); len(items) != 1 {
157			t.Fatalf("list holds %d records, want 1", len(items))
158		}
159	}
160	
161	// Strict-validation failures still produce no record: after a mix of 400s the
162	// list stays empty, and defaults never rescue an explicit null.
163	func TestRegressionInvalidInputLeavesNoRecord(t *testing.T) {
164		_, h := newTestRouter(t)
165	
166		template := `{
167		  "namespace": "ns", "name": "job-%d", "queue": "q", "priority": 1,
168		  "resources": {"cpu": 100, "memory": 64},
169		  "nodes": [{"name": "n", "cpu": 200, "memory": 128, "labels": {}}]
170		}`
171		valid := func(i int) string { return fmt.Sprintf(template, i) }
172	
173		bodies := []string{
174			// Explicit nulls where defaults only apply to omitted fields.
175			`{"namespace":"ns","name":"j1","queue":"q","priority":1,"resources":{"cpu":1,"memory":1},"selector":null,"nodes":[]}`,
176			`{"namespace":"ns","name":"j2","queue":"q","priority":1,"resources":{"cpu":1,"memory":1},"nodes":[{"name":"n","cpu":1,"memory":1,"labels":null}]}`,
177			// Unknown and duplicate fields.
178			`{"namespace":"ns","name":"j3","queue":"q","priority":1,"resources":{"cpu":1,"memory":1},"nodes":[],"bogus":1}`,
179			`{"namespace":"ns","name":"j4","queue":"q","priority":1,"resources":{"cpu":1,"memory":1},"nodes":[],"queue":"q2"}`,
180			// Trailing data.
181			valid(5) + ` {}`,
182			// Type, range, required and node-name-uniqueness failures.
183			`{"namespace":"ns","name":"j6","queue":"q","priority":"1","resources":{"cpu":1,"memory":1},"nodes":[]}`,
